package com.solegendary.reignofnether.sounds;

import com.solegendary.reignofnether.barfx.BarFx;
import it.unimi.dsi.fastutil.longs.Long2LongOpenHashMap;
import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.Level;
import net.minecraft.world.phys.Vec3;

/**
 * The mod's own sound effects (design/audio.md): every one is original and procedurally generated by
 * tools/gen_sfx.py into sounds/sfx/&lt;key&gt;_&lt;n&gt;.ogg, registered as "sfx.&lt;key&gt;" (SoundRegistrar) with its
 * variations listed in sounds.json, so Minecraft picks one at random each time.
 *
 * Two ways in:
 * <ul>
 *   <li>Battle chatter (shots, hits, deaths, collapses, builders at work) needs no call at all: SfxClient turns the
 *   BarFx events the client already receives into sounds, so a big fight costs no extra packets.</li>
 *   <li>Discrete server events (a gate swings, a trap springs, a game ender charges) call {@link #play} /
 *   {@link #playGlobal}. A positional sound rides the BarFx per-tick queue as one more event (batched per player,
 *   range filtered, nothing new on the wire); a global one (match moments) goes straight to every player.</li>
 * </ul>
 * Each sound has a category (the per-category volumes of the client config) and a client-side minimum gap; the
 * server adds its own per-place gap so a pile of identical events in one spot sends one sound.
 *
 * Keep the key list in step with tools/gen_sfx.py: the GameTest sounds_json_covers_every_registered_event fails on a
 * key without a sounds.json entry or a file.
 */
public enum Sfx {
    // ---- units: weapon classes (BarFx SHOT kinds, IMPACT kinds)
    SHOT_BOW("shot_bow", Category.UNITS, 0.45f, 2),
    SHOT_GUN("shot_gun", Category.UNITS, 0.6f, 2),
    SHOT_FIRE("shot_fire", Category.UNITS, 0.55f, 2),
    SHOT_HEAVY("shot_heavy", Category.UNITS, 0.8f, 3),
    SHOT_MAGIC("shot_magic", Category.UNITS, 0.5f, 2),
    SHOT_ROCKET("shot_rocket", Category.UNITS, 0.6f, 2),
    SHOT_THROWN("shot_thrown", Category.UNITS, 0.45f, 2),
    HIT_MELEE("hit_melee", Category.UNITS, 0.5f, 2),
    HIT_HEAVY("hit_heavy", Category.UNITS, 0.7f, 3),
    HIT_BUILDING("hit_building", Category.UNITS, 0.5f, 3),
    // ---- units: deaths, by the faction debris field of BarFx DEATH (index = BarFx.F_* - 1)
    DEATH_SUNFORGED("death_sunforged", Category.UNITS, 0.7f, 3),
    DEATH_GRAVEBOUND("death_gravebound", Category.UNITS, 0.7f, 3),
    DEATH_HORDE("death_horde", Category.UNITS, 0.7f, 3),
    DEATH_VERDANT("death_verdant", Category.UNITS, 0.7f, 3),
    DEATH_TIDE("death_tide", Category.UNITS, 0.7f, 3),
    DEATH_STORM("death_storm", Category.UNITS, 0.7f, 3),
    DEATH_BRASS("death_brass", Category.UNITS, 0.7f, 3),
    DEATH_LARGE("death_large", Category.UNITS, 1.0f, 6),
    // ---- buildings
    BUILT_SUNFORGED("built_sunforged", Category.BUILDINGS, 0.8f, 10),
    BUILT_GRAVEBOUND("built_gravebound", Category.BUILDINGS, 0.8f, 10),
    BUILT_HORDE("built_horde", Category.BUILDINGS, 0.8f, 10),
    BUILT_VERDANT("built_verdant", Category.BUILDINGS, 0.8f, 10),
    BUILT_TIDE("built_tide", Category.BUILDINGS, 0.8f, 10),
    BUILT_STORM("built_storm", Category.BUILDINGS, 0.8f, 10),
    BUILT_BRASS("built_brass", Category.BUILDINGS, 0.8f, 10),
    DESTROYED_SUNFORGED("destroyed_sunforged", Category.BUILDINGS, 1.0f, 8),
    DESTROYED_GRAVEBOUND("destroyed_gravebound", Category.BUILDINGS, 1.0f, 8),
    DESTROYED_HORDE("destroyed_horde", Category.BUILDINGS, 1.0f, 8),
    DESTROYED_VERDANT("destroyed_verdant", Category.BUILDINGS, 1.0f, 8),
    DESTROYED_TIDE("destroyed_tide", Category.BUILDINGS, 1.0f, 8),
    DESTROYED_STORM("destroyed_storm", Category.BUILDINGS, 1.0f, 8),
    DESTROYED_BRASS("destroyed_brass", Category.BUILDINGS, 1.0f, 8),
    // construction "loop": one quiet granule now and then near busy builders (BarFx NANO tint = faction); the cadence
    // is NanoCadence's, the volume 0.3 -> 0.2 (Oct 29: "workers buzzing as they build")
    NANO_SUNFORGED("nano_sunforged", Category.BUILDINGS, 0.2f, 10),
    NANO_GRAVEBOUND("nano_gravebound", Category.BUILDINGS, 0.2f, 10),
    NANO_HORDE("nano_horde", Category.BUILDINGS, 0.2f, 10),
    NANO_VERDANT("nano_verdant", Category.BUILDINGS, 0.2f, 10),
    NANO_TIDE("nano_tide", Category.BUILDINGS, 0.2f, 10),
    NANO_STORM("nano_storm", Category.BUILDINGS, 0.2f, 10),
    NANO_BRASS("nano_brass", Category.BUILDINGS, 0.2f, 10),
    RECLAIM_TICK("reclaim_tick", Category.BUILDINGS, 0.35f, 12),
    RECLAIM_DONE("reclaim_done", Category.BUILDINGS, 0.6f, 6),
    GATE_OPEN("gate_open", Category.BUILDINGS, 0.8f, 10),
    GATE_CLOSE("gate_close", Category.BUILDINGS, 0.8f, 10),
    TRAP_SPIKES("trap_spikes", Category.BUILDINGS, 0.9f, 4),
    TRAP_SNARE("trap_snare", Category.BUILDINGS, 0.9f, 4),
    TRAP_MINE("trap_mine", Category.BUILDINGS, 1.0f, 4),
    // ---- abilities, heroes, beasts
    POSSESS_ENTER("possess_enter", Category.ABILITIES, 0.8f, 10),
    POSSESS_EXIT("possess_exit", Category.ABILITIES, 0.7f, 10),
    HERO_BOON("hero_boon", Category.ABILITIES, 0.9f, 20),
    BEAST_TRUMPET("beast_trumpet", Category.ABILITIES, 0.9f, 60),
    BEAST_CHARGE("beast_charge", Category.ABILITIES, 1.0f, 20),
    BEAST_BREACH("beast_breach", Category.ABILITIES, 1.0f, 10),
    BEAST_DEVOUR("beast_devour", Category.ABILITIES, 0.9f, 20),
    BEAST_EMBARK("beast_embark", Category.ABILITIES, 0.8f, 20),
    // ---- game enders (design/big_units.md): everyone hears the start, the aim and the interception
    GAMEENDER_START("gameender_start", Category.ANNOUNCER, 0.9f, 40),
    GAMEENDER_STAGE("gameender_stage", Category.ANNOUNCER, 0.8f, 20),
    GAMEENDER_AIM("gameender_aim", Category.ANNOUNCER, 0.9f, 40),
    GAMEENDER_STRIKE("gameender_strike", Category.ANNOUNCER, 1.0f, 20),
    GAMEENDER_INTERCEPT("gameender_intercept", Category.ANNOUNCER, 0.9f, 20),
    // ---- start-position phase (maps/StartPhase; client side in MapClient)
    STARTPOS_BEGIN("startpos_begin", Category.UI, 0.7f, 20),
    STARTPOS_PLACE("startpos_place", Category.UI, 0.6f, 4),
    STARTPOS_TICK("startpos_tick", Category.UI, 0.5f, 10),
    STARTPOS_END("startpos_end", Category.UI, 0.7f, 20),
    // ---- match-start stingers per faction (short, original; "Music stingers" in the Sound settings)
    STINGER_SUNFORGED("stinger_sunforged", Category.ANNOUNCER, 0.7f, 40),
    STINGER_GRAVEBOUND("stinger_gravebound", Category.ANNOUNCER, 0.7f, 40),
    STINGER_HORDE("stinger_horde", Category.ANNOUNCER, 0.7f, 40),
    STINGER_VERDANT("stinger_verdant", Category.ANNOUNCER, 0.7f, 40),
    STINGER_TIDE("stinger_tide", Category.ANNOUNCER, 0.7f, 40),
    STINGER_STORM("stinger_storm", Category.ANNOUNCER, 0.7f, 40),
    STINGER_BRASS("stinger_brass", Category.ANNOUNCER, 0.7f, 40);

    /** The five volume groups of the Sound settings page (ANNOUNCER shares the announcer voice's volume). */
    public enum Category { UNITS, BUILDINGS, ABILITIES, ANNOUNCER, UI }

    public final String key;
    public final Category category;
    /** Base volume before the category volume, distance and crowd scaling. */
    public final float volume;
    /** Client: minimum game ticks between two plays of this sound anywhere (bounds a big fight's chatter). */
    public final int minGapTicks;

    Sfx(String key, Category category, float volume, int minGapTicks) {
        this.key = key;
        this.category = category;
        this.volume = volume;
        this.minGapTicks = minGapTicks;
    }

    private static final Sfx[] VALUES = values();

    /** By ordinal (the BarFx SFX event carries the ordinal in its kind byte); null if out of range. */
    public static Sfx byId(int id) {
        return id >= 0 && id < VALUES.length ? VALUES[id] : null;
    }

    // the seven factions in BarFx F_* order (1..7); index 0 = F_NONE
    private static final Sfx[] DEATHS = { null, DEATH_SUNFORGED, DEATH_GRAVEBOUND, DEATH_HORDE, DEATH_VERDANT, DEATH_TIDE,
        DEATH_STORM, DEATH_BRASS };
    private static final Sfx[] BUILT = { null, BUILT_SUNFORGED, BUILT_GRAVEBOUND, BUILT_HORDE, BUILT_VERDANT, BUILT_TIDE,
        BUILT_STORM, BUILT_BRASS };
    private static final Sfx[] DESTROYED = { null, DESTROYED_SUNFORGED, DESTROYED_GRAVEBOUND, DESTROYED_HORDE,
        DESTROYED_VERDANT, DESTROYED_TIDE, DESTROYED_STORM, DESTROYED_BRASS };
    private static final Sfx[] STINGERS = { null, STINGER_SUNFORGED, STINGER_GRAVEBOUND, STINGER_HORDE, STINGER_VERDANT,
        STINGER_TIDE, STINGER_STORM, STINGER_BRASS };
    // nano tints (BarFx N_*: SUNFORGED 0, GRAVEBOUND 1, HORDE 2, NEUTRAL 3, VERDANT 4, TIDE 5, STORM 6, BRASS 7)
    private static final Sfx[] NANO = { NANO_SUNFORGED, NANO_GRAVEBOUND, NANO_HORDE, NANO_SUNFORGED, NANO_VERDANT,
        NANO_TIDE, NANO_STORM, NANO_BRASS };

    /** A faction's death sound by BarFx.F_* (null for F_NONE: plain mobs keep their vanilla death sound). */
    public static Sfx death(int faction) {
        return faction > 0 && faction < DEATHS.length ? DEATHS[faction] : null;
    }

    public static Sfx built(int faction) {
        return faction > 0 && faction < BUILT.length ? BUILT[faction] : null;
    }

    public static Sfx destroyed(int faction) {
        return faction > 0 && faction < DESTROYED.length ? DESTROYED[faction] : null;
    }

    public static Sfx stinger(int faction) {
        return faction > 0 && faction < STINGERS.length ? STINGERS[faction] : null;
    }

    public static Sfx nano(int tint) {
        return tint >= 0 && tint < NANO.length ? NANO[tint] : NANO_SUNFORGED;
    }

    // ------------------------------------------------------------------ server side

    /**
     * Server: per (sound, 8-block cell) the game time it last went out. Several gates in one wall, a minefield going
     * off together or a stack of beasts charging as one send one sound per place, not one per building/unit.
     */
    private static final Long2LongOpenHashMap LAST_SENT = new Long2LongOpenHashMap();
    private static final int SERVER_GAP_TICKS = 4;

    static long cellKey(int id, double x, double z) {
        long cx = ((long) Math.floor(x / 8)) & 0xFFFFF, cz = ((long) Math.floor(z / 8)) & 0xFFFFF;
        return ((long) id << 40) | (cx << 20) | cz;
    }

    /** Plays this sound at a position for the players near it (safe to call from anywhere; client calls are ignored). */
    public void play(Level level, BlockPos pos) {
        if (pos != null)
            play(level, pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5, 1f, 1f);
    }

    public void play(Level level, Vec3 pos) {
        if (pos != null)
            play(level, pos.x, pos.y, pos.z, 1f, 1f);
    }

    /** Positional, with a volume factor and pitch. Returns true if it was queued (false: rate limited or client side). */
    public boolean play(Level level, double x, double y, double z, float volume, float pitch) {
        if (!(level instanceof ServerLevel sl))
            return false;
        long now = sl.getGameTime();
        long key = cellKey(ordinal(), x, z);
        long last = LAST_SENT.getOrDefault(key, Long.MIN_VALUE);
        if (last != Long.MIN_VALUE && now >= last && now - last < SERVER_GAP_TICKS)
            return false;
        if (LAST_SENT.size() > 4096)   // stale cells are never removed one by one; a rare reset is cheaper
            LAST_SENT.clear();
        LAST_SENT.put(key, now);
        BarFx.sfx(sl, x, y, z, ordinal(), volume, pitch, false);
        return true;
    }

    /** Every player hears it at once, wherever they look (match moments: a game ender wakes, takes aim, is stopped). */
    public void playGlobal(Level level, float volume, float pitch) {
        if (level instanceof ServerLevel sl)
            BarFx.sfx(sl, 0, 0, 0, ordinal(), volume, pitch, true);
    }

    /** Server stopping: forget the per-place gaps. */
    public static void clearServerState() {
        LAST_SENT.clear();
    }
}
